package com.lootbankhighlighter;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(LootBankHighlighterConfig.GROUP)
public interface LootBankHighlighterConfig extends Config
{
	String GROUP = "lootbankhighlighter";

	@ConfigItem(
		keyName = "highlightColor",
		name = "Highlight color",
		description = "Color used to outline matching items in the bank",
		hidden = true,
		position = 1
	)
	default Color highlightColor()
	{
		return new Color(255, 215, 0, 200); // gold, like a loadout highlight
	}

	@ConfigItem(
		keyName = "fillColor",
		name = "Fill color",
		description = "Fill color used behind matching items in the bank",
		hidden = true,
		position = 2
	)
	default Color fillColor()
	{
		return new Color(255, 215, 0, 40);
	}

	@ConfigItem(
		keyName = "onlyOneSourceAtATime",
		name = "Single source selection",
		description = "Only one loot source can be pinned/highlighted at a time (like a single loadout)",
		hidden = true,
		position = 3
	)
	default boolean onlyOneSourceAtATime()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackNewLoot",
		name = "Track new loot",
		description = "Record new drops while RuneLite Loot Tracker is enabled. Disable to pause tracking without removing saved records or bank filtering.",
		position = 0
	)
	default boolean trackNewLoot()
	{
		return true;
	}

	@ConfigItem(
		keyName = "persistRecordsAcrossSessions",
		name = "Save loot between sessions",
		description = "Save aggregated loot records to the config profile so they survive a client restart",
		position = 4
	)
	default boolean persistRecords()
	{
		return true;
	}
}

package com.lootbankhighlighter;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.List;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;
import java.util.Comparator;
import java.util.function.IntToLongFunction;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import javax.swing.JComboBox;
import javax.swing.JCheckBox;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.QuantityFormatter;

/**
 * Lists tracked loot sources the way the built-in Loot Tracker does: source
 * name, kill count, and every distinct item received with its icon and
 * quantity - plus an eye toggle to pin a source for the bank filter view.
 */
public class LootBankHighlighterPanel extends PluginPanel
{
	private final LootBankHighlighterPlugin plugin;
	private final ItemManager itemManager;
	private final ClientThread clientThread;
	private final JPanel listContainer = new ViewportWidthPanel();

	private final JComboBox<String> sortBox = new JComboBox<>(new String[]{"Most recent", "Highest value", "Name"});
	private final JCheckBox pinnedFirst = new JCheckBox("Pinned first", true);
	private final Set<String> collapsedSources = new HashSet<>();
	private final JButton undoButton = new JButton("Undo delete");
	private volatile int rebuildGeneration;

	private BufferedImage eyeOpenIcon;
	private BufferedImage eyeClosedIcon;
	private BufferedImage panelIcon;

	public LootBankHighlighterPanel(LootBankHighlighterPlugin plugin, ItemManager itemManager, ClientThread clientThread)
	{
		super(false);
		this.plugin = plugin;
		this.itemManager = itemManager;
		this.clientThread = clientThread;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		try
		{
			eyeOpenIcon = ImageUtil.loadImageResource(getClass(), "eye_open.png");
			eyeClosedIcon = ImageUtil.loadImageResource(getClass(), "eye_closed.png");
			panelIcon = ImageUtil.loadImageResource(getClass(), "loot_bank_icon.png");
		}
		catch (Exception ignored)
		{
		}

		JPanel titlePanel = new JPanel(new BorderLayout());
		titlePanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		titlePanel.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));

		if (panelIcon != null)
		{
			JLabel iconLabel = new JLabel(new ImageIcon(panelIcon));
			titlePanel.add(iconLabel, BorderLayout.WEST);
		}

		JLabel title = new JLabel("Pin a source to filter it into your bank");
		title.setFont(FontManager.getRunescapeSmallFont());
		title.setForeground(Color.WHITE);
		titlePanel.add(title, BorderLayout.CENTER);

		JButton importButton = new JButton("Import Loot Tracker History");
		importButton.setToolTipText("Import remembered loot from RuneLite's active character profile");
		importButton.addActionListener(e -> importLootTrackerHistory());
		titlePanel.add(importButton, BorderLayout.SOUTH);

		JPanel controls = new JPanel(new GridLayout(0, 1, 0, 4));
		controls.setOpaque(false);
		controls.add(sortBox);
		pinnedFirst.setOpaque(false);
		controls.add(pinnedFirst);
		undoButton.setVisible(false);
		undoButton.addActionListener(e -> plugin.undoDelete());
		controls.add(undoButton);
		JPanel top = new JPanel(new BorderLayout(0, 4));
		top.setOpaque(false);
		top.add(titlePanel, BorderLayout.NORTH);
		top.add(controls, BorderLayout.CENTER);
		add(top, BorderLayout.NORTH);
		sortBox.addActionListener(e -> rebuild());
		pinnedFirst.addActionListener(e -> rebuild());

		listContainer.setLayout(new BoxLayout(listContainer, BoxLayout.Y_AXIS));
		listContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JScrollPane scrollPane = new JScrollPane(listContainer);
		scrollPane.setBorder(BorderFactory.createEmptyBorder());
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);
		add(scrollPane, BorderLayout.CENTER);

		rebuild();
	}

	private void importLootTrackerHistory()
	{
		int choice = JOptionPane.showConfirmDialog(
			this,
			"<html>Import RuneLite's remembered Loot Tracker history for the active character?<br>"
				+ "Existing records will be kept, and repeated imports will not double their totals.</html>",
			"Import Loot Tracker History",
			JOptionPane.OK_CANCEL_OPTION,
			JOptionPane.QUESTION_MESSAGE);
		if (choice != JOptionPane.OK_OPTION)
		{
			return;
		}

		clientThread.invoke(() ->
		{
			LootBankHighlighterPlugin.ImportResult result = plugin.importLootTrackerHistory();
			SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(
				this, result.getMessage(), "Loot Tracker Import",
				result.isSuccess() ? JOptionPane.INFORMATION_MESSAGE : JOptionPane.WARNING_MESSAGE));
		});
	}

	public void rebuild()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::rebuild);
			return;
		}
		final int generation = ++rebuildGeneration;
		int sort = sortBox.getSelectedIndex();
		boolean pinsFirst = pinnedFirst.isSelected();
		clientThread.invoke(() ->
		{
			if (generation != rebuildGeneration) { return; }
			List<LootRecord> records = new ArrayList<>();
			Map<String, Long> totals = new HashMap<>();
			Set<String> pins = new HashSet<>(plugin.getSelectedSources());
			Map<Integer, Long> prices = new HashMap<>();
			for (LootRecord live : plugin.getLootRecords().values())
			{
				LootRecord record = live.copy();
				if (record.isEmpty()) { continue; }
				for (int id : record.getItems().keySet())
				{
					int canonical = itemManager.canonicalize(id);
					prices.computeIfAbsent(id, key -> itemManager.getItemPrice(canonical));
				}
				records.add(record);
				totals.put(record.getSourceName(), totalGeValue(record.getItems(), prices::get));
			}
			Comparator<LootRecord> order = sort == 1
				? Comparator.comparingLong((LootRecord r) -> totals.get(r.getSourceName())).reversed()
				: sort == 2 ? Comparator.comparing(LootRecord::getSourceName, String.CASE_INSENSITIVE_ORDER)
				: Comparator.comparingLong(LootRecord::getLastUpdatedMillis).reversed();
			order = order.thenComparing(LootRecord::getSourceName);
			if (pinsFirst)
			{
				order = Comparator.comparing((LootRecord r) -> !pins.contains(r.getSourceName())).thenComparing(order);
			}
			records.sort(order);
			String undoSource = plugin.getUndoSource();
			SwingUtilities.invokeLater(() ->
			{
				if (generation != rebuildGeneration) { return; }
				listContainer.removeAll();
				for (LootRecord record : records)
				{
					listContainer.add(buildSourcePanel(record, totals.get(record.getSourceName()),
						pins.contains(record.getSourceName())));
				}
				if (records.isEmpty())
				{
					JLabel empty = new JLabel("<html>No loot tracked yet.<br>Kill something or import history.</html>");
					empty.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
					listContainer.add(empty);
				}
				undoButton.setVisible(undoSource != null);
				undoButton.setToolTipText(undoSource == null ? null : "Restore " + undoSource
					+ " (available until restart or history import)");
				listContainer.revalidate();
				listContainer.repaint();
				revalidate();
			});
		});
	}

	private JPanel buildSourcePanel(LootRecord record, long total, boolean selected)
	{
		String source = record.getSourceName();

		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARKER_GRAY_COLOR),
			BorderFactory.createEmptyBorder(4, 6, 4, 6)));
		wrapper.setBackground(selected ? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARK_GRAY_COLOR);

		// Keep the value on the first row and controls on a separate row to avoid clipping.
		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);

		String kills = record.getKillCount() + (record.getKillCount() == 1 ? " kill" : " kills");
		JLabel nameLabel = new JLabel(source);
		nameLabel.setToolTipText(source);
		nameLabel.setFont(FontManager.getRunescapeSmallFont());
		nameLabel.setForeground(selected ? Color.YELLOW : Color.WHITE);
		JPanel heading = new JPanel(new BorderLayout(6, 0));
		heading.setOpaque(false);
		heading.add(nameLabel, BorderLayout.CENTER);

		JLabel valueLabel = new JLabel("...", SwingConstants.RIGHT);
		valueLabel.setFont(FontManager.getRunescapeSmallFont());
		valueLabel.setForeground(Color.LIGHT_GRAY);
		valueLabel.setToolTipText("Loading estimated GE value...");
		heading.add(valueLabel, BorderLayout.EAST);
		header.add(heading, BorderLayout.NORTH);

		JLabel killsLabel = new JLabel(kills);
		killsLabel.setFont(FontManager.getRunescapeSmallFont());
		killsLabel.setForeground(Color.LIGHT_GRAY);
		header.add(killsLabel, BorderLayout.CENTER);

		Map<Integer, Integer> items = record.getItems();
		valueLabel.setText(QuantityFormatter.quantityToStackSize(total) + " gp");
		valueLabel.setToolTipText("Estimated GE value of tracked loot: "
			+ QuantityFormatter.formatNumber(total) + " gp");

		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		buttons.setOpaque(false);

		JButton collapseButton = new JButton(collapsedSources.contains(source) ? "+" : "-");
		collapseButton.setToolTipText(collapsedSources.contains(source) ? "Expand loot" : "Collapse loot");
		collapseButton.addActionListener(e ->
		{
			if (!collapsedSources.remove(source)) { collapsedSources.add(source); }
			rebuild();
		});
		buttons.add(collapseButton);

		JButton eyeButton = new JButton();
		eyeButton.setToolTipText(selected
			? "Unpin: stop filtering this loot into your bank"
			: "Pin: filter this loot into its own bank view");
		eyeButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		BufferedImage icon = selected ? eyeOpenIcon : eyeClosedIcon;
		if (icon != null)
		{
			eyeButton.setIcon(new ImageIcon(icon));
		}
		else
		{
			eyeButton.setText(selected ? "\uD83D\uDC41" : "○");
		}
		eyeButton.addActionListener(e ->
		{
			plugin.toggleSelected(source);
			rebuild();
		});
		buttons.add(eyeButton);

		JButton clearButton = new JButton("x");
		clearButton.setToolTipText("Forget this loot record");
		clearButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		clearButton.addActionListener(e -> plugin.clearRecord(source));
		buttons.add(clearButton);

		JPanel details = new JPanel(new BorderLayout());
		details.setOpaque(false);
		details.add(killsLabel, BorderLayout.CENTER);
		details.add(buttons, BorderLayout.EAST);
		header.add(details, BorderLayout.CENTER);
		wrapper.add(header, BorderLayout.NORTH);

		if (collapsedSources.contains(source))
		{
			return wrapper;
		}

		// Item grid: icon + quantity for every distinct item from this source
		JPanel itemGrid = new JPanel(new GridLayout(0, 6, 2, 2));
		itemGrid.setOpaque(false);
		for (Map.Entry<Integer, Integer> entry : items.entrySet())
		{
			itemGrid.add(buildItemIcon(source, entry.getKey(), entry.getValue()));
		}
		wrapper.add(itemGrid, BorderLayout.CENTER);

		return wrapper;
	}

	static long totalGeValue(Map<Integer, Integer> items, IntToLongFunction priceLookup)
	{
		long total = 0;
		for (Map.Entry<Integer, Integer> item : items.entrySet())
		{
			total += priceLookup.applyAsLong(item.getKey()) * item.getValue();
		}
		return total;
	}

	private JLabel buildItemIcon(String source, int itemId, int quantity)
	{
		JLabel label = new JLabel();
		JPopupMenu menu = new JPopupMenu();
		JMenuItem remove = new JMenuItem("Remove item");
		remove.setToolTipText("Remove this entire item stack from this loot source");
		remove.addActionListener(e -> plugin.removeItem(source, itemId));
		menu.add(remove);
		label.setComponentPopupMenu(menu);
		label.setToolTipText("Loading item details...");
		clientThread.invoke(() ->
		{
			// Item definitions must be read on the client thread; Swing updates belong on the EDT.
			int canonicalId = itemManager.canonicalize(itemId);
			ItemComposition item = itemManager.getItemComposition(canonicalId);
			String tooltip = buildToolTip(canonicalId, item.getMembersName(), quantity,
				itemManager.getItemPrice(canonicalId), item.getHaPrice());
			SwingUtilities.invokeLater(() -> label.setToolTipText(tooltip));
		});
		label.setVerticalAlignment(SwingConstants.CENTER);
		label.setHorizontalAlignment(SwingConstants.CENTER);
		label.setPreferredSize(new Dimension(40, 32));

		AsyncBufferedImage image = itemManager.getImage(itemId, quantity, quantity > 1);
		image.addTo(label);

		return label;
	}

	static String buildToolTip(int itemId, String name, int quantity, long gePrice, long haPrice)
	{
		String escapedName = name.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
		StringBuilder tooltip = new StringBuilder("<html>");
		tooltip.append(escapedName).append(" x ").append(QuantityFormatter.formatNumber(quantity));
		if (itemId != ItemID.COINS)
		{
			appendPrice(tooltip, "GE", quantity, gePrice);
			if (itemId != ItemID.PLATINUM)
			{
				appendPrice(tooltip, "HA", quantity, haPrice);
			}
		}
		return tooltip.append("</html>").toString();
	}

	private static void appendPrice(StringBuilder tooltip, String type, int quantity, long unitPrice)
	{
		tooltip.append("<br>").append(type).append(": ")
			.append(QuantityFormatter.quantityToStackSize(unitPrice * quantity));
		if (quantity > 1)
		{
			tooltip.append(" (").append(QuantityFormatter.quantityToStackSize(unitPrice)).append(" ea)");
		}
	}

	private static class ViewportWidthPanel extends JPanel implements Scrollable
	{
		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return Math.max(16, visibleRect.height - 16);
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package com.lootbankhighlighter;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.lang.reflect.Type;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Objects;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.InventoryID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.ItemComposition;
import net.runelite.api.ScriptID;
import net.runelite.api.Varbits;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
		name = "Loot Bank Highlighter",
		description = "Pin a Loot Tracker entry with the eye icon and see it filtered into its own view in your bank, like an Inventory Setups loadout",
		tags = {"loot", "tracker", "bank", "inventory", "setups", "highlight"}
)
public class LootBankHighlighterPlugin extends Plugin
{
	private static final String CONFIG_KEY_RECORDS = "lootRecordsJson";
	private static final String LOOT_TRACKER_CONFIG_GROUP = "loottracker";
	private static final String LOOT_TRACKER_DROP_PREFIX = "drops_";

	// Mirrors the real bank's own item grid layout so repositioned items line up correctly.
	private static final int ITEMS_PER_ROW = 8;
	private static final int ITEM_VERTICAL_SPACING = 36;
	private static final int ITEM_HORIZONTAL_SPACING = 48;
	private static final int ITEM_ROW_START = 51;
	private static final int EMPTY_BANK_SLOT_ID = 6512;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	LootBankHighlighterConfig config;

	@Inject
	private Gson gson;

	@Inject
	private BankSearch bankSearch;

	private LootBankHighlighterPanel panel;
	private NavigationButton navButton;
	private final Deque<DeletedRecord> deletedRecords = new ArrayDeque<>();

	/** sourceName -> aggregated loot */
	private final Map<String, LootRecord> lootRecords = new LinkedHashMap<>();

	/** Currently pinned source(s) whose items should be highlighted/tabbed in the bank. */
	private final Set<String> selectedSources = new java.util.LinkedHashSet<>();

	/** The source currently being filtered into its own bank view, or null for the normal bank. */
	private String activeTabSource;

	@Provides
	LootBankHighlighterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LootBankHighlighterConfig.class);
	}

	@Override
	protected void startUp()
	{
		deletedRecords.clear();
		loadRecords();

		panel = new LootBankHighlighterPanel(this, itemManager, clientThread);
		refreshPanel();

		BufferedImage icon;
		try
		{
			icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		}
		catch (Exception e)
		{
			// no custom icon asset provided - draw a simple placeholder so the plugin still loads
			icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = icon.createGraphics();
			g.setColor(Color.YELLOW);
			g.fillOval(2, 2, 12, 12);
			g.dispose();
		}

		NavigationButton.NavigationButtonBuilder builder = NavigationButton.builder()
				.tooltip("Loot Bank Highlighter")
				.icon(icon)
				.priority(6)
				.panel(panel);
		navButton = builder.build();
		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown()
	{
		if (activeTabSource != null)
		{
			deactivateTabView();
		}
		deletedRecords.clear();
		clientToolbar.removeNavigation(navButton);
		saveRecords();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// no-op hook kept for future use (e.g. clearing per-session state on login)
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (!config.trackNewLoot())
		{
			return;
		}
		String source = event.getName();
		record(source, event.getItems().stream()
				.collect(java.util.stream.Collectors.toMap(i -> i.getId(), i -> i.getQuantity(), Integer::sum)), event.getAmount());
	}

	void record(String source, Map<Integer, Integer> items, int amount)
	{
		LootRecord rec = lootRecords.computeIfAbsent(source, LootRecord::new);
		rec.addKillCount(amount);
		items.forEach(rec::addItem);
		saveRecords();
		SwingUtilities.invokeLater(this::refreshPanel);
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && !selectedSources.isEmpty() && activeTabSource == null)
		{
			activateTabView(selectedSources.iterator().next());
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.BANK.getId() || activeTabSource == null)
		{
			return;
		}

		// Rebuild native widgets first: deposits can move stacks to different slots.
		// BANKMAIN_FINISHBUILDING then applies our filter to the rebuilt widgets.
		clientThread.invokeLater(() ->
		{
			if (activeTabSource != null)
			{
				bankSearch.layoutBank();
			}
		});
	}

	/**
	 * The real workhorse: fires right when the game finishes laying out the bank grid.
	 * We hide every real item widget that doesn't match the pinned loot, and pack the
	 * matching real widgets into a clean grid - so everything stays natively
	 * draggable/clickable, because it IS the real bank doing the work.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		// Leave BANKMAIN_SEARCHING alone: pinning loot is not a native text search.
		// Forcing its result also forces the search button on and prevents opening input.
		if (event.getScriptId() != ScriptID.BANKMAIN_FINISHBUILDING || activeTabSource == null)
		{
			return;
		}

		applyFilteredBankLayout();
	}

	private void applyFilteredBankLayout()
	{
		if (activeTabSource == null)
		{
			return;
		}

		Widget itemContainer = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
		if (itemContainer == null)
		{
			return;
		}

		Widget[] children = itemContainer.getDynamicChildren();
		if (children == null)
		{
			return;
		}

		LootRecord record = lootRecords.get(activeTabSource);
		// Loot Tracker preserves noted IDs, but deposited notes become unnoted bank items.
		// Normalize only for matching, preserving the saved drops and quantities.
		Set<Integer> matchIds = record == null ? Collections.emptySet() : record.getItems().keySet()
				.stream().map(itemManager::canonicalize).collect(Collectors.toSet());
		net.runelite.api.ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		Item[] bankItems = bank == null ? new Item[0] : bank.getItems();

		Widget bankTitle = client.getWidget(ComponentID.BANK_TITLE_BAR);
		if (bankTitle != null)
		{
			bankTitle.setText(activeTabSource + " - loot");
		}

		int placed = 0;
		for (Widget widget : children)
		{
			if (widget == null)
			{
				continue;
			}

			int itemId = widget.getItemId();
			boolean isRealItem = itemId > 0 && itemId != EMPTY_BANK_SLOT_ID;
			if (!isRealItem)
			{
				continue; // leave bank furniture (tab buttons, backgrounds, etc.) alone
			}

			// A stale widget may still have this item ID even though its slot is empty.
			// Validate the exact slot so redepositing the item cannot revive that widget.
			// The native rebuild has already applied text/value search and bank tab visibility.
			// Narrow that result instead of reviving items that native search excluded.
			if (!widget.isSelfHidden() && matchIds.contains(itemManager.canonicalize(itemId))
					&& isCurrentBankSlot(bankItems, widget.getIndex(), itemId))
			{
				int adjX = (placed % ITEMS_PER_ROW) * ITEM_HORIZONTAL_SPACING + ITEM_ROW_START;
				int adjY = (placed / ITEMS_PER_ROW) * ITEM_VERTICAL_SPACING;

				widget.setHidden(false);
				widget.setOriginalX(adjX);
				widget.setOriginalY(adjY);
				widget.revalidate();
				placed++;
			}
			else
			{
				widget.setHidden(true);
			}
		}
	}

	static boolean isCurrentBankSlot(Item[] bankItems, int slot, int itemId)
	{
		if (slot < 0 || slot >= bankItems.length)
		{
			return false;
		}
		Item item = bankItems[slot];
		return item != null && item.getId() == itemId && item.getQuantity() > 0;
	}

	// ---- activation, driven by the panel's eye-icon buttons ----

	public boolean isSelected(String sourceName)
	{
		return selectedSources.contains(sourceName);
	}

	public void toggleSelected(String sourceName)
	{
		clientThread.invoke(() -> toggleSelectedOnClient(sourceName));
	}

	private void toggleSelectedOnClient(String sourceName)
	{
		if (selectedSources.contains(sourceName))
		{
			selectedSources.remove(sourceName);

			if (sourceName.equals(activeTabSource))
			{
				clientThread.invoke(() -> deactivateTabView());
			}
		}
		else
		{
			selectedSources.clear();

			selectedSources.add(sourceName);

			clientThread.invoke(() ->
			{
				Widget bankMain = client.getWidget(ComponentID.BANK_CONTAINER);

				if (bankMain != null && !bankMain.isHidden())
				{
					activateTabView(sourceName);
				}
			});
		}

		SwingUtilities.invokeLater(this::refreshPanel);
	}

	private void activateTabView(String source)
	{
		activeTabSource = source;
		clientThread.invokeLater(() ->
		{
			client.setVarbit(Varbits.CURRENT_BANK_TAB, 0);
			bankSearch.reset(true);
		});
	}

	private void deactivateTabView()
	{
		activeTabSource = null;
		clientThread.invokeLater(() ->
		{
			client.setVarbit(Varbits.CURRENT_BANK_TAB, 0);
			bankSearch.reset(true);
		});
	}

	public Set<String> getSelectedSources()
	{
		return selectedSources;
	}

	public Map<String, LootRecord> getLootRecords()
	{
		return lootRecords;
	}

	/**
	 * Combined item-id -> quantity map across every currently-selected/pinned source.
	 * Used by the optional highlight-style overlay.
	 */
	public Map<Integer, Integer> getHighlightedItems()
	{
		Map<Integer, Integer> combined = new LinkedHashMap<>();
		for (String source : selectedSources)
		{
			LootRecord rec = lootRecords.get(source);
			if (rec != null)
			{
				rec.getItems().forEach((id, qty) -> combined.merge(id, qty, Integer::sum));
			}
		}
		return combined;
	}

	public void removeItem(String sourceName, int itemId)
	{
		clientThread.invoke(() ->
		{
			LootRecord record = lootRecords.get(sourceName);
			if (record == null || record.getItems().remove(itemId) == null)
			{
				return;
			}

			// Empty sources are hidden in the sidebar, so release their pin as well.
			if (record.isEmpty())
			{
				selectedSources.remove(sourceName);
				if (sourceName.equals(activeTabSource))
				{
					deactivateTabView();
				}
			}
			else if (sourceName.equals(activeTabSource))
			{
				bankSearch.layoutBank();
			}
			saveRecords();
			refreshPanel();
		});
	}

	public void clearRecord(String sourceName)
	{
		clientThread.invoke(() ->
		{
			LootRecord removed = lootRecords.remove(sourceName);
			if (removed == null)
			{
				return;
			}
			deletedRecords.push(new DeletedRecord(removed, selectedSources.remove(sourceName),
				configManager.getRSProfileKey()));
			if (sourceName.equals(activeTabSource))
			{
				deactivateTabView();
			}
			saveRecords();
			refreshPanel();
		});
	}

	public String getUndoSource()
	{
		// Never restore a deletion into a different character's session.
		if (!deletedRecords.isEmpty()
			&& !Objects.equals(deletedRecords.peek().profile, configManager.getRSProfileKey()))
		{
			deletedRecords.clear();
		}
		return deletedRecords.isEmpty() ? null : deletedRecords.peek().record.getSourceName();
	}

	public void undoDelete()
	{
		clientThread.invoke(() ->
		{
			if (getUndoSource() == null)
			{
				refreshPanel();
				return;
			}
			DeletedRecord deleted = deletedRecords.pop();
			String source = deleted.record.getSourceName();
			LootRecord current = lootRecords.get(source);
			if (current == null)
			{
				lootRecords.put(source, deleted.record);
			}
			else
			{
				current.restoreDeleted(deleted.record);
			}
			if (deleted.pinned && selectedSources.isEmpty()
				&& !selectedSources.contains(source))
			{
				toggleSelected(source);
			}
			saveRecords();
			refreshPanel();
		});
	}

	private static class DeletedRecord
	{
		private final LootRecord record;
		private final boolean pinned;
		private final String profile;

		private DeletedRecord(LootRecord record, boolean pinned, String profile)
		{
			this.record = record;
			this.pinned = pinned;
			this.profile = profile;
		}
	}

	public void refreshPanel()
	{
		if (panel != null)
		{
			panel.rebuild();
		}
	}

	public ItemComposition getItemComposition(int itemId)
	{
		return itemManager.getItemComposition(itemId);
	}

	public ImportResult importLootTrackerHistory()
	{
		String profileKey = configManager.getRSProfileKey();
		if (profileKey == null || profileKey.isEmpty())
		{
			return new ImportResult(false, "Log into a character before importing Loot Tracker history.");
		}

		Map<String, ImportedLoot> bySource = new LinkedHashMap<>();
		int readableRecords = 0;
		for (String key : configManager.getRSProfileConfigurationKeys(
			LOOT_TRACKER_CONFIG_GROUP, profileKey, LOOT_TRACKER_DROP_PREFIX))
		{
			String json = configManager.getConfiguration(LOOT_TRACKER_CONFIG_GROUP, profileKey, key);
			if (json == null || json.isEmpty())
			{
				continue;
			}

			try
			{
				ImportedLoot imported = gson.fromJson(json, ImportedLoot.class);
				if (imported == null || imported.name == null || imported.name.isEmpty()
					|| imported.drops == null || imported.drops.length < 2)
				{
					continue;
				}

				readableRecords++;
				ImportedLoot combined = bySource.computeIfAbsent(imported.name, ImportedLoot::new);
				combined.kills = saturatedAdd(combined.kills, Math.max(0, imported.kills));
				for (int i = 0; i + 1 < imported.drops.length; i += 2)
				{
					int itemId = imported.drops[i];
					int quantity = imported.drops[i + 1];
					if (itemId > 0 && quantity > 0)
					{
						combined.items.merge(itemId, quantity, LootBankHighlighterPlugin::saturatedAdd);
					}
				}
			}
			catch (RuntimeException ex)
			{
				log.debug("Skipping unreadable Loot Tracker record {}", key, ex);
			}
		}

		if (readableRecords == 0)
		{
			return new ImportResult(false,
				"No remembered Loot Tracker history was found for the active character. "
					+ "Make sure Loot Tracker's Remember loot setting is enabled.");
		}

		// Imported snapshots overlap deleted history; invalidate undo to avoid counting it twice.
		deletedRecords.clear();
		int changedSources = 0;
		for (ImportedLoot imported : bySource.values())
		{
			if (imported.items.isEmpty())
			{
				continue;
			}
			LootRecord destination = lootRecords.computeIfAbsent(imported.name, LootRecord::new);
			if (destination.mergeSnapshot(imported.kills, imported.items))
			{
				changedSources++;
			}
		}

		saveRecords();
		refreshPanel();
		if (changedSources == 0)
		{
			return new ImportResult(true, "Everything in Loot Tracker was already imported.");
		}
		return new ImportResult(true,
			"Imported or updated " + changedSources + (changedSources == 1 ? " loot source." : " loot sources."));
	}

	private static int saturatedAdd(int first, int second)
	{
		long result = (long) first + second;
		return result > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) result;
	}

	private static class ImportedLoot
	{
		private String name;
		private int kills;
		private int[] drops;
		private final Map<Integer, Integer> items = new LinkedHashMap<>();

		private ImportedLoot()
		{
		}

		private ImportedLoot(String name)
		{
			this.name = name;
		}
	}

	public static class ImportResult
	{
		private final boolean success;
		private final String message;

		private ImportResult(boolean success, String message)
		{
			this.success = success;
			this.message = message;
		}

		public boolean isSuccess()
		{
			return success;
		}

		public String getMessage()
		{
			return message;
		}
	}

	// ---- persistence ----

	private void saveRecords()
	{
		if (!config.persistRecords())
		{
			return;
		}
		configManager.setConfiguration(LootBankHighlighterConfig.GROUP, CONFIG_KEY_RECORDS, gson.toJson(lootRecords));
	}

	private void loadRecords()
	{
		if (!config.persistRecords())
		{
			return;
		}
		String json = configManager.getConfiguration(LootBankHighlighterConfig.GROUP, CONFIG_KEY_RECORDS);
		if (json == null || json.isEmpty())
		{
			return;
		}
		try
		{
			Type type = new TypeToken<LinkedHashMap<String, LootRecord>>() {}.getType();
			Map<String, LootRecord> saved = gson.fromJson(json, type);
			if (saved != null)
			{
				lootRecords.putAll(saved);
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to load saved loot records", e);
		}
	}
}

package com.lootbankhighlighter;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Aggregated loot for a single source ("Zulrah", "Barrows chest", clue name, etc).
 * We keep a running total of item id -> quantity seen, mirroring what the
 * built-in Loot Tracker panel would show for that source.
 */
public class LootRecord
{
	private final String sourceName;
	// itemId -> total quantity ever received from this source
	private final Map<Integer, Integer> items = new LinkedHashMap<>();
	private long lastUpdatedMillis;
	private int killCount;

	public LootRecord(String sourceName)
	{
		this.sourceName = sourceName;
	}

	public int getKillCount()
	{
		return killCount;
	}

	public void incrementKillCount()
	{
		killCount++;
	}

	public void addKillCount(int amount)
	{
		killCount = saturatedAdd(killCount, Math.max(0, amount));
	}

	public boolean mergeSnapshot(int importedKillCount, Map<Integer, Integer> importedItems)
	{
		boolean changed = false;
		if (importedKillCount > killCount)
		{
			killCount = importedKillCount;
			changed = true;
		}

		for (Map.Entry<Integer, Integer> entry : importedItems.entrySet())
		{
			Integer current = items.get(entry.getKey());
			if (current == null || entry.getValue() > current)
			{
				items.put(entry.getKey(), entry.getValue());
				changed = true;
			}
		}

		if (changed)
		{
			lastUpdatedMillis = System.currentTimeMillis();
		}
		return changed;
	}

	public String getSourceName()
	{
		return sourceName;
	}

	public Map<Integer, Integer> getItems()
	{
		return items;
	}

	public long getLastUpdatedMillis()
	{
		return lastUpdatedMillis;
	}

	public void addItem(int itemId, int quantity)
	{
		items.merge(itemId, quantity, Integer::sum);
		lastUpdatedMillis = System.currentTimeMillis();
	}

	public LootRecord copy()
	{
		LootRecord copy = new LootRecord(sourceName);
		copy.items.putAll(items);
		copy.killCount = killCount;
		copy.lastUpdatedMillis = lastUpdatedMillis;
		return copy;
	}

	/** Restore deleted history without losing drops received after deletion. */
	public void restoreDeleted(LootRecord deleted)
	{
		killCount = saturatedAdd(killCount, deleted.killCount);
		deleted.items.forEach((id, quantity) -> items.merge(id, quantity, LootRecord::saturatedAdd));
		lastUpdatedMillis = Math.max(lastUpdatedMillis, deleted.lastUpdatedMillis);
	}

	private static int saturatedAdd(int a, int b)
	{
		return (int) Math.min(Integer.MAX_VALUE, (long) a + b);
	}

	public boolean isEmpty()
	{
		return items.isEmpty();
	}
}

